// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListPeople People to choose from on the start page
	// (GET /api/people)
	ListPeople(ctx context.Context, request ListPeopleRequestObject) (ListPeopleResponseObject, error)
	// PutPerson Add a person, or change their name, language or plan
	// (PUT /api/people/{key})
	PutPerson(ctx context.Context, request PutPersonRequestObject) (PutPersonResponseObject, error)
	// AddRound Record a finished round
	// (POST /api/people/{key}/rounds)
	AddRound(ctx context.Context, request AddRoundRequestObject) (AddRoundResponseObject, error)
	// GetToday The person's plan for a day, in their language, with their stats
	// (GET /api/people/{key}/today)
	GetToday(ctx context.Context, request GetTodayRequestObject) (GetTodayResponseObject, error)
	// ListPlans All plans, each with its newest version
	// (GET /api/plans)
	ListPlans(ctx context.Context, request ListPlansRequestObject) (ListPlansResponseObject, error)
	// GetPlan The newest version of a plan, in the form it is edited in
	// (GET /api/plans/{key})
	GetPlan(ctx context.Context, request GetPlanRequestObject) (GetPlanResponseObject, error)
	// PutPlan Create a plan or save a new version of it
	// (PUT /api/plans/{key})
	PutPlan(ctx context.Context, request PutPlanRequestObject) (PutPlanResponseObject, error)
	// GetHealth Liveness check
	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
}

// StrictHandlerFunc and StrictMiddlewareFunc are type aliases rather than
// distinct named types, so middleware written against one generated package
// can be shared with every other generated package using the same framework.
type StrictHandlerFunc = func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc = func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListPeople operation middleware
func (sh *strictHandler) ListPeople(w http.ResponseWriter, r *http.Request) {
	var request ListPeopleRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error) {
		return sh.ssi.ListPeople(ctx, request.(ListPeopleRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListPeople")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ListPeopleResponseObject); ok {
		if err := validResponse.VisitListPeopleResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

